\define theme-rgb() {{{ [[$:/TopStats/ThemeColors]getindex{$:/TopStats/Theme}] ~[[$:/TopStats/ThemeColors]getindex[Midnight]] +[trim[]] }}}

/* --- MASTER AESTHETIC --- */

html, body.tc-body, .tc-page-container {
  background-color: #020617 !important;
  background-image: <$text text={{{ [[$:/TopStats/ThemePatterns]getindex{$:/TopStats/Theme}] ~[[$:/TopStats/ThemePatterns]getindex[Midnight]] }}} /> !important;
  background-attachment: fixed !important;
  color: #a6adbb !important;
  font-family: 'Inter', sans-serif !important;
  font-size: 0.85rem !important;
  line-height: 1.5 !important;
  word-wrap: break-word !important;
  fill: #FFFFFF !important;
}

html {
    font-size: 100% !important;
}

.tc-page-container {
  margin: 0 !important; 
  padding-top: 34px !important;
  min-height: 100vh !important;
  display: flex !important;
  flex-direction: column !important;
  background: transparent !important;
}

/* Story River - WIDER LAYOUT (1600px Max) */
.tc-story-river {
  padding: 0 10px !important;
  width: 98% !important;
  max-width: 1900px !important;
  margin: 0 auto !important;
  position: relative !important; 
  z-index: 10 !important; 
  box-sizing: border-box !important;
}

@media (min-width: 1000px) {
  .tc-story-river {
    position: relative !important;
    left: 0px !important;
    top: 0px !important;
    padding: 8px 16px !important;
  }
}
/* --- STORY BACKDROP ALIGNMENT FIX --- */
.story-backdrop {
  text-align: left !important;
}

.story-backdrop td {
  text-align: left !important;
}

.story-backdrop td[align="right"] {
  text-align: left !important;
}

/* Story backdrop image cell sizing */
.story-backdrop td:first-child,
.story-backdrop th:first-child {
  width: 1% !important;
  white-space: nowrap !important;
  padding-right: 0.35rem !important;
  padding-left: 0.35rem !important;
  position: relative !important;
  background-image: <$text text={{{ [[$:/TopStats/ThemeBackdropIcons]getindex{$:/TopStats/Theme}] ~[[$:/TopStats/ThemeBackdropIcons]getindex[Midnight]] }}}/> !important;
  background-size: 87px 86px !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  min-width: 87px !important;
  min-height: 86px !important;
}

.story-backdrop td:first-child img,
.story-backdrop th:first-child img {
  visibility: hidden !important;
  width: 87px !important;
  height: 86px !important;
  min-width: 87px !important;
  min-height: 86px !important;
  max-width: 87px !important;
  max-height: 86px !important;
}

/* Story backdrop table tweaks */
.story-backdrop table {
  font-weight: 600 !important;
}

.story-backdrop th,
.story-backdrop td {
  padding: 0.45rem 0.75rem !important;
}

.story-backdrop tbody tr:hover td,
.story-backdrop .table-hover tbody tr:hover td {
  background-color: transparent !important;
}

.story-backdrop td,
.story-backdrop th {
  border-bottom: 1px solid rgba(255, 255, 255, 0.03) !important;
}

/* --- NAVBAR FINAL (Static, No Hover) --- */
.ts-glass-header {
    position: fixed !important; 
    top: 0; 
    left: 0; 
    right: 0; 
    height: 32px; 
    background: rgba(15, 23, 42, 0.05) !important; 
    backdrop-filter: blur(25px); 
    -webkit-backdrop-filter: blur(25px); 
    border: none !important;
    border-top: none !important;
    border-bottom: none !important;
    border-left: none !important;
    border-right: none !important;
    z-index: 5000 !important;
    display: flex; 
    align-items: center; 
    justify-content: flex-start !important;
    padding: 0 1rem; 
    gap: 1rem;
}

.ts-header-link {
    text-decoration: none !important; 
    background: transparent !important;
    color: rgba(255,255,255,0.7) !important;
    display: flex; 
    align-items: center; 
    pointer-events: auto;
}

.ts-glass-header-title {
    font-size: 0.75rem; 
    font-weight: 600;
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.ts-header-brand {
    color: #ffffff !important;
    font-weight: 700;
}

.ts-header-subtitle {
    color: rgb(<<theme-rgb>>) !important;
}



/* Header logo sizing */
.ts-glass-header-title img {
    height: 18px !important;
    width: auto !important;
    max-height: 18px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    margin-right: 0.5rem !important;
}


/* Header GitHub link styling */
.ts-header-link-github {
    text-decoration: none !important;
    color: inherit !important;
    display: inline-flex !important;
    align-items: center !important;
}

.ts-header-link-github:hover {
    text-decoration: none !important;
    filter: brightness(1.2) !important;
}

.ts-header-link-github:visited {
    color: inherit !important;
}

.ts-header-buttons {
    margin-left: auto;
    display: flex;
    gap: 0.5rem;
    align-items: center;
    pointer-events: auto;
}

.ts-glass-logo { width: 1.1rem; height: 1.1rem; background: rgba(20, 184, 166, 0.2); color: rgb(<<theme-rgb>>); border: 1px solid rgba(<<theme-rgb>>, 0.2); border-radius: 3px; display: flex; align-items: center; justify-content: center; font-size: 0.55rem; font-weight: 800; }

/* Minions table alignment (caption has radios) */
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) {
    width: 100% !important;
    table-layout: auto !important;
}
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) thead td,
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) thead th,
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) tbody td {
    padding: 0.65rem 0.85rem !important;
    vertical-align: middle !important;
}
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) thead td,
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) thead th {
    font-size: 0.75rem !important;
    font-weight: 700 !important;
    color: #ffffff !important;
    text-transform: uppercase !important;
    white-space: nowrap !important;
}
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) thead tr {
    border-bottom: 1px solid rgba(255,255,255,0.08) !important;
}

/* Respect align attributes in sortable headers */
.table-caption-top-left.table-hover.sortable thead th[align="center"],
.table-caption-top-left.table-hover.sortable thead td[align="center"] {
    text-align: center !important;
}
.table-caption-top-left.table-hover.sortable thead th[align="right"],
.table-caption-top-left.table-hover.sortable thead td[align="right"] {
    text-align: right !important;
}
.table-caption-top-left.table-hover.sortable thead th[align="left"],
.table-caption-top-left.table-hover.sortable thead td[align="left"] {
    text-align: left !important;
}

/* Minions top table borders (caption has radios) */
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) {
    border: 1px solid rgba(255,255,255,0.12) !important;
    border-radius: 8px !important;
    overflow: hidden !important;
}
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) th,
.table-caption-top-left.table-hover.sortable:has(caption .tc-radio) td {
    border: 1px solid rgba(255,255,255,0.08) !important;
}

/* --- TABLE STYLING --- */
/* Notice callout for inline-styled h3 notes */
/* Modern select styling */
select:not([multiple]) {
    appearance: none !important;
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    background: rgba(21, 25, 30, 0.55) !important;
    border: 1px solid rgba(255, 255, 255, 0.12) !important;
    color: #e2e8f0 !important;
    padding: 0.55rem 2.1rem 0.55rem 0.85rem !important;
    border-radius: 12px !important;
    font-weight: 600 !important;
    font-size: 0.85rem !important;
    line-height: 1.25 !important;
    box-shadow: 0 14px 32px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255,255,255,0.04) !important;
    backdrop-filter: blur(20px) saturate(130%) !important;
    -webkit-backdrop-filter: blur(20px) saturate(130%) !important;
    transition: border-color 0.2s ease, box-shadow 0.2s ease, background-color 0.2s ease !important;
    background-image: linear-gradient(45deg, transparent 50%, rgba(<<theme-rgb>>, 0.9) 50%),
                      linear-gradient(135deg, rgba(<<theme-rgb>>, 0.9) 50%, transparent 50%);
    background-position: calc(100% - 18px) 55%, calc(100% - 12px) 55%;
    background-size: 6px 6px !important;
    background-repeat: no-repeat !important;
}
select:not([multiple]):hover {
    border-color: rgba(<<theme-rgb>>, 0.45) !important;
    background: rgba(21, 25, 30, 0.7) !important;
    box-shadow: 0 16px 34px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(<<theme-rgb>>, 0.2) inset !important;
}
select:not([multiple]):focus {
    outline: none !important;
    border-color: rgba(<<theme-rgb>>, 0.6) !important;
    box-shadow: 0 0 0 3px rgba(<<theme-rgb>>, 0.18), 0 16px 36px rgba(0, 0, 0, 0.45) !important;
}
select:not([multiple]) option {
    background: rgba(15, 23, 42, 0.95) !important;
    color: #e2e8f0 !important;
}
select:not([multiple]) option:checked {
    background: rgba(<<theme-rgb>>, 0.25) !important;
    color: #f8fafc !important;
}
/* High scores layout: add breathing room between table blocks */
/* High scores layout: force wrap + column sizing */
.tc-tab-content .flex-row {
    flex-wrap: wrap !important;
    align-items: flex-start !important;
}
.tc-tab-content .flex-row > .flex-col {
    flex: 1 1 320px !important;
    min-width: 320px !important;
    max-width: 100% !important;
}
.tc-tab-content .flex-row {
    gap: 1.5rem !important;
    flex-wrap: wrap !important;
}
.tc-tab-content .flex-col {
    margin-bottom: 1.5rem !important;
}
.tc-tab-content table {
    margin: 0 0 1.25rem 0 !important;
}
/* Attendance Review: emphasize subheader totals rows (thead after tbody) */
table.table-caption-top tbody + thead td {
    background: rgba(<<theme-rgb>>, 0.12) !important;
    color: #e2e8f0 !important;
    font-weight: 700 !important;
    font-size: 0.72rem !important;
    text-transform: uppercase !important;
    letter-spacing: 0.03em !important;
    border-top: 1px solid rgba(255, 255, 255, 0.14) !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14) !important;
}
table.table-caption-top tbody + thead tr {
    background: rgba(15, 23, 42, 0.55) !important;
}
table {
    width: 100%;
    margin: 1rem 0 !important;
    border-collapse: collapse !important;
    border-spacing: 0 !important;
    font-size: 0.85rem !important;
    color: #a6adbb !important;
    border: none !important;
    border-top: none !important;
    border-bottom: none !important;
    border-left: none !important;
    border-right: none !important;
    background: transparent !important;
}

th {
    background-color: transparent !important;
    color: #ffffff !important;
    text-transform: uppercase;
    font-weight: 700 !important;
    font-size: 0.75rem !important;
    padding: 1rem !important;
    border: none !important;
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
    border-bottom: 1px solid rgba(255,255,255,0.1) !important;
    text-align: left;
    white-space: nowrap;
}

td {
    padding: 0.75rem 1rem !important;
    border: none !important;
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.03) !important;
    background-color: transparent !important;
    transition: background-color 0.1s;
    vertical-align: middle !important;
}


/* Table row borders */
.tc-tiddler-body table tbody tr td,
.tc-tab-content table tbody tr td {
  border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;
}
/* Keep icon + text on one line in table cells */
td img,
td svg {
    display: inline-block !important;
    vertical-align: middle !important;
}

td img + br,
td svg + br {
    display: none !important;
}

td img + *,
td svg + * {
    display: inline !important;
    vertical-align: middle !important;
    margin-left: 0.35rem !important;
}

td * + img,
td * + svg {
    display: inline-block !important;
    vertical-align: middle !important;
    margin-left: 0.35rem !important;
}

td br,
th br {
    display: none !important;
}

/* Override old_style.css borders - aggressive */
table, table th, table td, table tr {
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
}

/* Remove any remaining table borders */
.tc-tab-content table,
.tc-tab-content table th,
.tc-tab-content table td,
.tc-tab-content table tr {
    border-top: none !important;
    border-left: none !important;
    border-right: none !important;
}

/* Tailwind border override */
.border,
.flex-col.border,
div.border,
.tc-tab-content .border {
    border: none !important;
    border-top: none !important;
    border-bottom: none !important;
    border-left: none !important;
    border-right: none !important;
}

/* Column controls wrapping fix */
.col-controls,
div[class*="col-controls"],
.tc-tab-content .col-controls {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 0.5rem !important;
    width: 100% !important;
    max-width: 100% !important;
    overflow: visible !important;
}

/* Comprehensive overflow prevention */
.tc-tiddler-body,
.tc-tab-content,
.tc-tiddler-frame {
    overflow-x: auto !important;
    overflow-y: visible !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
}

/* Ensure all child elements respect container width */
.tc-tiddler-body > *,
.tc-tab-content > * {
    max-width: 100% !important;
    box-sizing: border-box !important;
}

/* Force flex containers to wrap and not overflow */
.tc-tiddler-body div,
.tc-tab-content div {
    max-width: 100% !important;
    overflow-wrap: break-word !important;
    word-wrap: break-word !important;
}

/* Flex items should shrink if needed */
.tc-tiddler-body [class*="flex"],
.tc-tab-content [class*="flex"] {
    flex-shrink: 1 !important;
    min-width: 0 !important;
}

/* Icon sizing in headers only */
th img, th svg {
    width: 20px !important;
    height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    object-fit: contain !important;
}

/* Special handling for header icons wrapped in links or spans */
th a img, th span img, th a svg, th span svg {
    width: 20px !important;
    height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
}


/* Log Summary tables: no row borders */
[data-tiddler-title$="-Log-Summary"] .tc-tiddler-body tbody tr td {
  border-bottom: none !important;
}
/* Hover effect */
/* Log Summary tables: font size */
[data-tiddler-title$="-Log-Summary"] .tc-tiddler-body table {
  font-size: 0.85rem !important;
}

tbody tr:hover td,
.table-hover tbody tr:hover,
.table-hover tbody tr:hover td {
    background-color: rgba(255, 255, 255, 0.008) !important;
    color: #a6adbb !important;
}

/* Commander Summary Table - Compact & Left Aligned */
.tc-tiddler-frame table:not(.tc-tab-content *) {
    width: auto !important;
    max-width: 60% !important;
    font-size: 0.7rem !important;
}

.tc-tiddler-frame table:not(.tc-tab-content *) th {
    font-size: 0.65rem !important;
    padding: 0.6rem 0.8rem !important;
}

.tc-tiddler-frame table:not(.tc-tab-content *) td {
    font-size: 0.85rem !important;
    padding: 0.5rem 0.8rem !important;
}

/* Icon sizing for compact summary table headers */
.tc-tiddler-frame table:not(.tc-tab-content *) img,
.tc-tiddler-frame table:not(.tc-tab-content *) svg {
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    object-fit: contain !important;
}

.tc-tiddler-frame table:not(.tc-tab-content *) th img,
.tc-tiddler-frame table:not(.tc-tab-content *) th svg,
.tc-tiddler-frame table:not(.tc-tab-content *) td img,
.tc-tiddler-frame table:not(.tc-tab-content *) td svg {
    width: 20px !important;
    height: 20px !important;
    min-width: 20px !important;
    min-height: 20px !important;
    max-width: 20px !important;
    max-height: 20px !important;
    display: inline-block !important;
    vertical-align: middle !important;
    object-fit: contain !important;
}

/* Override: Tab content tables are full width */
.tc-tiddler-frame .tc-tab-content table {
    width: 100% !important;
    max-width: 100% !important;
    font-size: 0.85rem !important;
}

.tc-tiddler-frame .tc-tab-content table th {
    font-size: 0.75rem !important;
    padding: 1rem !important;
}

.tc-tiddler-frame .tc-tab-content table td {
    font-size: 0.85rem !important;
    padding: 0.75rem 1rem !important;
}

/* --- TAG STYLING --- */
span.tc-tag-label,
button.tc-tag-label,
a.tc-tag-label {
    color: rgb(<<theme-rgb>>) !important;
    font-weight: 600 !important;
    font-size: 0.7rem !important;
    text-transform: uppercase;
    line-height: 1.2em;
    white-space: break-spaces;
    background: rgba(<<theme-rgb>>, 0.12) !important;
    border: 1px solid rgba(<<theme-rgb>>, 0.22) !important;
    border-radius: 6px !important;
    padding: 0.18rem 0.5rem !important;
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    text-decoration: none !important;
    box-shadow: 0 0 8px rgba(<<theme-rgb>>, 0.15), 
                0 0 16px rgba(<<theme-rgb>>, 0.08) !important;
    transition: all 0.2s ease;
}

span.tc-tag-label:hover,
button.tc-tag-label:hover,
a.tc-tag-label:hover {
    background: rgba(<<theme-rgb>>, 0.18) !important;
    color: rgb(<<theme-rgb>>) !important; filter: brightness(1.3) !important;
    box-shadow: 0 0 12px rgba(<<theme-rgb>>, 0.2), 
                0 0 24px rgba(<<theme-rgb>>, 0.12) !important;
}

.tc-btn-invisible {
    cursor: pointer;
    color: #FFFFFF;
    fill: #FFFFFF;
}

/* --- LINK STYLING --- */
/* Base link styles with TiddlyWiki-specific classes */
a,
a:link,
a.tc-tiddlylink,
a.tc-tiddlylink-resolves,
a.tc-tiddlylink-missing,
a.tc-tiddlylink-external,
a.tc-tiddlylink .tc-toc-caption,
.tc-tiddler-body a,
.tc-tiddler-body a.tc-tiddlylink,
.tc-tab-content a,
.tc-tab-content a.tc-tiddlylink,
.tc-sidebar-scrollable a,
.tc-sidebar-scrollable a.tc-tiddlylink,
.tc-story-river a,
.tc-story-river a.tc-tiddlylink,
.tc-toc a,
.tc-toc a.tc-tiddlylink,
.tc-table-of-contents a,
.tc-table-of-contents a.tc-tiddlylink {
    color: rgb(<<theme-rgb>>) !important;
    text-decoration: none !important;
    transition: color 0.2s, filter 0.2s;
}

/* Links containing buttons should inherit color */
a.tc-tiddlylink .tc-btn-invisible,
a.tc-tiddlylink-resolves .tc-btn-invisible,
a .tc-btn-invisible {
    color: inherit !important;
}

a:visited,
a.tc-tiddlylink:visited,
a.tc-tiddlylink-resolves:visited,
.tc-tiddler-body a:visited,
.tc-tab-content a:visited,
.tc-sidebar-scrollable a:visited,
.tc-story-river a:visited,
.tc-toc a:visited,
.tc-table-of-contents a:visited {
    color: rgba(<<theme-rgb>>, 0.75) !important;
}

a:hover,
a.tc-tiddlylink:hover,
a.tc-tiddlylink-resolves:hover,
a.tc-tiddlylink-missing:hover,
a.tc-tiddlylink-external:hover,
.tc-tiddler-body a:hover,
.tc-tab-content a:hover,
.tc-sidebar-scrollable a:hover,
.tc-story-river a:hover,
.tc-toc a:hover,
.tc-table-of-contents a:hover {
    color: rgb(<<theme-rgb>>) !important;
    filter: brightness(1.3) !important;
    text-decoration: underline !important;
    text-shadow: 0 0 8px rgba(<<theme-rgb>>, 0.5) !important;
}

a:active,
a.tc-tiddlylink:active,
a.tc-tiddlylink-resolves:active,
.tc-tiddler-body a:active,
.tc-tab-content a:active,
.tc-sidebar-scrollable a:active,
.tc-story-river a:active,
.tc-toc a:active,
.tc-table-of-contents a:active {
    color: rgb(<<theme-rgb>>) !important;
    filter: brightness(1.5) !important;
}

/* --- RADIO BUTTON STYLING --- */
/* Container for radio button groups */
.tc-tab-content > p,
.tc-tiddler-body > p {
    display: flex !important;
    flex-wrap: wrap !important;
    gap: 0.3rem !important;
    align-items: center !important;
}

/* Individual radio button labels */
.tc-tab-content label,
.tc-tiddler-body label {
    display: inline-flex !important;
    align-items: center !important;
    gap: 0.4rem !important;
    padding: 0.5rem 0.6rem !important;
    margin: 0 !important;
    background: rgba(<<theme-rgb>>, 0.12) !important;
    border: 1px solid rgba(<<theme-rgb>>, 0.22) !important;
    border-radius: 6px !important;
    box-shadow: 0 0 8px rgba(<<theme-rgb>>, 0.15), 
                0 0 16px rgba(<<theme-rgb>>, 0.08) !important;
    transition: all 0.2s ease !important;
    cursor: pointer !important;
    white-space: nowrap !important;
    line-height: 1 !important;
}

.tc-tab-content label:hover,
.tc-tiddler-body label:hover {
    background: rgba(<<theme-rgb>>, 0.18) !important;
    box-shadow: 0 0 12px rgba(<<theme-rgb>>, 0.2), 
                0 0 24px rgba(<<theme-rgb>>, 0.12) !important;
}

/* Radio buttons themselves */
input[type="radio"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    -moz-appearance: none !important;
    width: 14px !important;
    height: 14px !important;
    min-width: 14px !important;
    min-height: 14px !important;
    border: 2px solid rgba(<<theme-rgb>>, 0.5) !important;
    border-radius: 3px !important;
    background: rgba(15, 23, 42, 0.6) !important;
    cursor: pointer !important;
    position: relative !important;
    margin: 0 !important;
    padding: 0 !important;
    transition: all 0.2s ease !important;
