/* --- DIRTY STATE (CORE COMPATIBLE) --- */
/* Default State: Clean visible, Dirty hidden */
.tc-image-save-button-dynamic-clean { display: inline-block !important; }
.tc-image-save-button-dynamic-dirty { display: none !important; }

/* Dirty State: Toggled by body.tc-dirty */
body.tc-dirty .tc-image-save-button-dynamic-clean { display: none !important; }
body.tc-dirty .tc-image-save-button-dynamic-dirty { 
    display: inline-block !important; 
    stroke: #ef4444 !important;
    fill: none !important;
    animation: pulse 2s ease-in-out infinite !important; 
}

@keyframes pulse { 
    0%, 100% { opacity: 1; } 
    50% { opacity: 0.7; } 
}


